{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 청년시설 입주 시 주소를 서울로 옮겨야 하는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울시 청년 기본 조례 제21조제4항제1호는 입주 대상자를 '서울에서 활동하는 19세부터 39세까지의 개인 및 단체(대표자)'로 정하고 있으며, 주소 이전을 입주 요건으로 규정하고 있지 않다. 만 27세는 제3조제1호의 청년(19세 이상 39세 이하) 연령 범위에 해당하므로, 서울에서 활동한다는 요건을 충족하면 주소 이전 없이도 입주 대상자에 해당할 수 있다. 다만 '서울에서 활동' 여부의 구체적 판단 기준은 원문에 제시되어 있지 않다.",
          "b_ids": "청년:제21조제4항제1호, 청년:제3조제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
